/** @type {import('ts-jest').JestConfigWithTsJest} */
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  moduleDirectories: ['node_modules', 'src'],
  testMatch: [
    '**/__tests__/**/*.test.ts',
    '**/tests/**/*.test.ts'
  ],
  moduleFileExtensions: ['ts', 'js', 'json'],
  // 设置环境变量（在测试框架加载之前执行）
  setupFiles: ['./src/__tests__/env-setup.ts'],
  collectCoverageFrom: [
    'src/**/*.ts',
    '!src/index.ts',
    '!src/scripts/**',
    '!src/__tests__/**'
  ],
  coverageDirectory: 'coverage',
  coverageReporters: ['text', 'lcov', 'clover'],
  testTimeout: 30000,
  verbose: true,
  transform: {
    '^.+\\.ts$': ['ts-jest', {
      tsconfig: 'tsconfig.json',
    }],
  },
};

/// <reference types="vitest" />
import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
    },
  },
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./tests/setup.ts'],
    include: ['tests/**/*.test.{ts,tsx}', 'src/**/*.test.{ts,tsx}'],
    coverage: {
      provider: 'v8',
      reporter: ['text', 'lcov', 'html'],
      include: ['src/**/*.{ts,tsx}'],
      exclude: ['src/main.tsx'],
    },
  },
});

import express from 'express';
import cors from 'cors';
import { config } from './config';
import { initDB } from './config/database';
import authRoutes from './routes/auth';
import productRoutes from './routes/products';
import cartRoutes from './routes/cart';
import orderRoutes from './routes/orders';

const app = express();

/** 中间件 */
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

/** 健康检查 */
app.get('/api/health', (_req, res) => {
  res.json({
    success: true,
    message: 'ShopEase 商城服务运行中',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/** 路由注册 */
app.use('/api/auth', authRoutes);
app.use('/api/products', productRoutes);
app.use('/api/cart', cartRoutes);
app.use('/api/orders', orderRoutes);

/** 404 处理 */
app.use((_req, res) => {
  res.status(404).json({
    success: false,
    message: '请求的资源不存在',
  });
});

/** 全局错误处理 */
app.use((err: Error, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
  console.error('服务器错误:', err);
  res.status(500).json({
    success: false,
    message: config.isDev ? err.message : '服务器内部错误',
  });
});

/** 启动服务器（非测试环境下）*/
if (!config.isTest) {
  initDB();
  app.listen(config.port, () => {
    console.log(`\n🛒  ShopEase 商城服务已启动`);
    console.log(`📡  API地址: http://localhost:${config.port}/api`);
    console.log(`🏥 健康检查: http://localhost:${config.port}/api/health\n`);
  });
}

export default app;

import { useEffect } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuthStore } from './store/authStore';

// 页面组件
import HomePage from './pages/HomePage';
import ProductListPage from './pages/ProductListPage';
import ProductDetailPage from './pages/ProductDetailPage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import CartPage from './pages/CartPage';
import OrderListPage from './pages/OrderListPage';
import OrderDetailPage from './pages/OrderDetailPage';
import AdminPage from './pages/AdminPage';
import ProfilePage from './pages/ProfilePage';

// 组件
import AppLayout from './components/AppLayout';
import AuthGuard from './components/AuthGuard';
import AdminGuard from './components/AdminGuard';

function App() {
  const init = useAuthStore((state) => state.init);

  useEffect(() => {
    init();
  }, [init]);

  return (
    <Routes>
      {/* 公开页面 */}
      <Route element={<AppLayout />}>
        <Route path="/" element={<HomePage />} />
        <Route path="/products" element={<ProductListPage />} />
        <Route path="/products/:id" element={<ProductDetailPage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />

        {/* 需要登录的页面 */}
        <Route
          path="/cart"
          element={
            <AuthGuard>
              <CartPage />
            </AuthGuard>
          }
        />
        <Route
          path="/orders"
          element={
            <AuthGuard>
              <OrderListPage />
            </AuthGuard>
          }
        />
        <Route
          path="/orders/:id"
          element={
            <AuthGuard>
              <OrderDetailPage />
            </AuthGuard>
          }
        />
        <Route
          path="/profile"
          element={
            <AuthGuard>
              <ProfilePage />
            </AuthGuard>
          }
        />

        {/* 管理员页面 */}
        <Route
          path="/admin/*"
          element={
            <AdminGuard>
              <AdminPage />
            </AdminGuard>
          }
        />

        {/* 404 重定向到首页 */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  );
}

export default App;

import { initDB, clearDB, getDB } from '../config/database';

/**
 * 测试环境初始化
 * - 初始化内存 SQLite 数据库
 * - 创建所有表结构
 */
export function setupTestDB(): void {
  initDB();
}

/**
 * 每个测试用例运行前清空数据
 */
export function clearTestDB(): void {
  clearDB();
}

/**
 * 关闭数据库连接（所有测试完成后调用）
 */
export function closeTestDB(): void {
  const { closeDB } = require('../config/database');
  closeDB();
}

/**
 * 获取测试用的数据库实例
 */
export { getDB };

/** 测试环境变量设置 */
process.env.NODE_ENV = 'test';
process.env.DATABASE_PATH = ':memory:';
process.env.JWT_SECRET = 'test-secret-key';
process.env.JWT_EXPIRES_IN = '7d';

import '@testing-library/jest-dom';
import { vi } from 'vitest';

// 模拟 window.matchMedia
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: vi.fn().mockImplementation((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  })),
});

// 模拟 localStorage
const localStorageMock = (() => {
  let store: Record<string, string> = {};
  return {
    getItem: (key: string) => store[key] || null,
    setItem: (key: string, value: string) => {
      store[key] = value;
    },
    removeItem: (key: string) => {
      delete store[key];
    },
    clear: () => {
      store = {};
    },
    get length() {
      return Object.keys(store).length;
    },
    key: (index: number) => Object.keys(store)[index] || null,
  };
})();

Object.defineProperty(window, 'localStorage', {
  value: localStorageMock,
});
